/** Longest accepted attribute key, including the first character. */
const TELEMETRY_KEY_MAX_LENGTH = 128;
/** Longest accepted attribute value. Each distinct metric value is its own series. */
const TELEMETRY_VALUE_MAX_LENGTH = 256;
/** Most keys one session may store on one signal. Spans, metrics, and logs each have their own cap. */
const TELEMETRY_MAX_KEYS = 32;
const KEY = /^[A-Za-z][A-Za-z0-9._-]*$/;
/**
 * Check a telemetry attribute map. `existing` is the session bag the call
 * would merge into. The call throws before any write when a key, a value,
 * or the resulting key count is not allowed.
 */
export function validateTelemetryAttributes(attributes, existing, reserved) {
    const cleaned = {};
    for (const [key, value] of Object.entries(attributes)) {
        if (!KEY.test(key) || key.length > TELEMETRY_KEY_MAX_LENGTH) {
            throw new Error(`telemetry attribute "${key}" must match [A-Za-z][A-Za-z0-9._-]* and be at most ${TELEMETRY_KEY_MAX_LENGTH} characters`);
        }
        if (reserved?.has(key) === true) {
            throw new Error(`telemetry attribute "${key}" is reserved; the runtime always sets it`);
        }
        if (typeof value !== "string") {
            throw new Error(`telemetry attribute "${key}" must be a string`);
        }
        if (value.length === 0 || value.length > TELEMETRY_VALUE_MAX_LENGTH) {
            throw new Error(`telemetry attribute "${key}" value must be 1 to ${TELEMETRY_VALUE_MAX_LENGTH} characters`);
        }
        cleaned[key] = value;
    }
    const next = new Set([...Object.keys(existing), ...Object.keys(cleaned)]);
    if (next.size > TELEMETRY_MAX_KEYS) {
        throw new Error(`telemetry attributes are limited to ${TELEMETRY_MAX_KEYS} keys per session`);
    }
    return cleaned;
}
